//! Where to go: metric key → the lab page and tab that shows (and changes) it.
//!
//! The table mirrors `web/src/labs/registry.ts` (lab routes and titles) and
//! each lab's `TABS`; a unit test parses the registry so the two cannot
//! drift apart silently. Lookups are tables of tuples rather than `match`
//! arms on dotted strings, because the API catalogue is generated by scanning
//! for `"module.method" =>` arms.

use serde::{Deserialize, Serialize};

/// A place in the app: `href` is the hash route to open (`#` + href).
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Where {
    /// Route path, e.g. `/ergonomics` or `/systems`.
    pub route: String,
    /// Tab id inside the page (`?tab=`), when the page has tabs.
    pub tab: Option<String>,
    /// Human label, e.g. "Human Factors Lab → Legibility & eyebox".
    pub label: String,
    /// Lab (or page) title alone, e.g. "Human Factors Lab".
    pub page: String,
    /// Tab label alone, e.g. "Legibility & eyebox".
    pub tab_label: Option<String>,
    /// Full route with query, e.g. `/ergonomics?tab=display`.
    pub href: String,
}

