/// Systems Studio tab labels (`web/src/pages/Systems.tsx`).
const STUDIO_TABS: &[(&str, &str)] = &[
    ("overview", "Mission control"),
    ("concept", "Concept"),
    ("requirements", "Requirements"),
    ("architecture", "Architecture"),
    ("traceability", "Traceability"),
    ("vmodel", "V-model"),
    ("trades", "Trade studies"),
    ("risks", "Risks (FMEA)"),
    ("budgets", "Budgets"),
    ("roadmap", "Roadmap"),
    ("report", "Report & templates"),
];

fn lab(id: &str) -> Option<(&'static str, &'static str)> {
    LABS.iter().find(|l| l.0 == id).map(|l| (l.1, l.2))
}

/// A Systems Studio tab, optionally opening one requirement's drawer.
pub fn studio(tab: &str, req: Option<&str>) -> Where {
    let tl = STUDIO_TABS.iter().find(|t| t.0 == tab).map(|t| t.1).unwrap_or("Overview");
    let mut href = format!("/systems?tab={tab}");
    if let Some(r) = req {
        href += &format!("&req={r}");
    }
    Where {
        route: "/systems".into(),
        tab: Some(tab.into()),
        label: format!("Systems Studio → {tl}"),
        page: "Systems Studio".into(),
        tab_label: Some(tl.into()),
        href,
    }
}

/// The lab tab that shows a metric. Budget roll-ups (`budget.*`, `bom.*`)
/// live in Systems Studio → Budgets; unknown prefixes fall back to the
/// requirement in Systems Studio.
pub fn for_metric(key: &str, req: Option<&str>) -> Where {
    if key.starts_with("budget.") || key.starts_with("bom.") {
        return studio("budgets", None);
    }
    let hit = METRIC_TABS.iter().find(|(k, ..)| key.starts_with(k));
    let Some(&(_, id, tab, tab_label)) = hit else {
        return studio("requirements", req);
    };
    let Some((route, title)) = lab(id) else {
        return studio("requirements", req);
    };
    if tab.is_empty() {
        return Where {
            route: route.into(),
            tab: None,
            label: title.into(),
            page: title.into(),
            tab_label: None,
            href: route.into(),
        };
    }
    Where {
        route: route.into(),
        tab: Some(tab.into()),
        label: format!("{title} → {tab_label}"),
        page: title.into(),
        tab_label: Some(tab_label.into()),
        href: format!("{route}?tab={tab}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn labs_match_the_web_registry() {
        let reg = include_str!("../../../../../web/src/labs/registry.ts");
        for (id, route, title) in LABS {
            let needle = format!("id: '{id}', path: '{route}', title: '{title}'");
            assert!(reg.contains(&needle), "registry.ts has no entry `{needle}`");
        }
        // every registry lab is known here
        let n = reg.matches("{ id: '").count();
        assert_eq!(n, LABS.len(), "registry.ts lists {n} labs, routes.rs {}", LABS.len());
    }

    #[test]
    fn metric_routes() {
        let w = for_metric("ergonomics.outdoor_contrast", Some("R-047"));
        assert_eq!(w.href, "/ergonomics?tab=display");
        assert_eq!(w.label, "Human Factors Lab → Legibility & eyebox");
        assert_eq!(for_metric("power.battery_life_h", None).tab.as_deref(), Some("discharge"));
        assert_eq!(for_metric("power.avg_power_mw", None).tab.as_deref(), Some("budget"));
        assert_eq!(for_metric("thermal.max_skin_c", None).route, "/power");
        assert_eq!(for_metric("budget.battery_life_h", None).href, "/systems?tab=budgets");
        assert_eq!(for_metric("molding.min_draft_deg", None).href, "/molding");
        assert_eq!(for_metric("nope.x", Some("R-9")).href, "/systems?tab=requirements&req=R-9");
    }
}
